    'admin_shadow-saas-grip.abort_failed_prefix' => 'Failed to abort sync: ',
    'admin_shadow-saas-grip.abort_grip_confirm' => 'Abort the running Grip sync?',
    'admin_shadow-saas-grip.abort_hero_confirm' => 'Abort the running HERO sync?',
    'admin_shadow-saas-grip.about_grip_body' => 'Grip Security discovers and continuously monitors SaaS-of-Record applications across your environment.
This integration:<br><br>
<strong>&bull; Mirrors Grip data:</strong> Pulls the full SaaS / users / alerts inventory into <code>shadow_saas_grip_*</code> tables.<br>
<strong>&bull; Hydrates Shadow SaaS:</strong> Projects each SaaS app into the existing Shadow SaaS list, normalizing the URL to its registrable domain so vendor matching works the same as a CSV import.<br>
<strong>&bull; Tracks risk:</strong> Persists Grip\'s risk score, sanction tag, OAuth-scope counts, AI-depth classification, MFA / SAML support, and primary-contact metadata.<br>
<strong>&bull; Stays fresh:</strong> Re-runs on the configured cron schedule; admins can also trigger an immediate background run with the "Run Now" button above.',
    'admin_shadow-saas-grip.about_grip_heading' => 'About the Grip Integration',
    'admin_shadow-saas-grip.about_hero_body' => 'HERO Security discovers third-party SaaS vendors and the issues affecting them across your environment.
This integration:<br><br>
<strong>&bull; Mirrors HERO data:</strong> Pulls vendors / issues / per-vendor users into <code>shadow_saas_hero_*</code> tables.<br>
<strong>&bull; Hydrates Shadow SaaS:</strong> Projects each vendor into the existing Shadow SaaS list by registrable domain, so matching works the same as a CSV import.<br>
<strong>&bull; Tracks risk:</strong> Derives a 1-5 risk score from the worst open issue per vendor (the same 1-5 scale Grip uses) and records the vendor\'s status and engagement aspects.<br>
<strong>&bull; Stays fresh:</strong> Re-runs on the shared Scheduled Rehydration job; admins can also trigger an immediate run with the "Run Now" button below.',
    'admin_shadow-saas-grip.about_hero_heading' => 'About the HERO Integration',
    'admin_shadow-saas-grip.api_key_label' => 'API Key',
    'admin_shadow-saas-grip.api_reference_heading' => 'API Reference',
    'admin_shadow-saas-grip.api_token_help' => 'Sent as the <code>access-token</code> HTTP header on every request. Leave blank to keep the existing token.',
    'admin_shadow-saas-grip.api_token_label' => 'API Token',
    'admin_shadow-saas-grip.api_url_host_not_allowed' => 'API URL host is not allowed.',
    'admin_shadow-saas-grip.api_url_invalid' => 'API URL must be a valid http(s) URL.',
    'admin_shadow-saas-grip.api_url_label' => 'API URL',
    'admin_shadow-saas-grip.apps_with_users_suffix' => ' apps with users',
    'admin_shadow-saas-grip.client_id_label' => 'Client ID',
    'admin_shadow-saas-grip.client_secret_label' => 'Client Secret',
    'admin_shadow-saas-grip.currently_holding_prefix' => 'Currently holding ',
    'admin_shadow-saas-grip.data_source_help' => '<strong>Live</strong> calls the Grip API for each page (always current, heavier on the API). <strong>Local (Hydrated/cached)</strong> serves the hydrated <code>shadow_saas_grip_*</code> tables in the database - lighter on the API - and a missing per-app snapshot is fetched from the API once, then cached. In Local mode, each sync <strong>fully refreshes</strong> the data: the Grip mirror tables are truncated and re-hydrated from the API.',
    'admin_shadow-saas-grip.data_source_label' => 'Data source',
    'admin_shadow-saas-grip.data_source_live' => 'Live - query the Grip API on every view',
    'admin_shadow-saas-grip.data_source_local' => 'Local (Hydrated/cached) - serve from the database',
    'admin_shadow-saas-grip.download_postman_json' => 'Download Postman (JSON)',
    'admin_shadow-saas-grip.download_swagger_yaml' => 'Download Swagger (YAML)',
    'admin_shadow-saas-grip.enable_grip' => 'Enable Grip Security integration',
    'admin_shadow-saas-grip.enable_hero' => 'Enable HERO Security integration',
    'admin_shadow-saas-grip.enable_scheduled_rehydration' => 'Enable scheduled rehydration',
    'admin_shadow-saas-grip.enable_zscaler' => 'Enable Zscaler URL-Category blocking on Deny',
    'admin_shadow-saas-grip.enter_admin_api_key' => 'Enter administrator API key',
    'admin_shadow-saas-grip.failed_truncate_prefix' => 'Failed to truncate ',
    'admin_shadow-saas-grip.flow_grip_breach_label' => 'Flow Grip breach information into Breach&nbsp;/&nbsp;Cyber Alerts',
    'admin_shadow-saas-grip.grip_all_cleared_p1' => 'All Grip data cleared: ',
    'admin_shadow-saas-grip.grip_all_cleared_p2' => ' mirror table(s) truncated, ',
    'admin_shadow-saas-grip.grip_all_cleared_p3' => ' Shadow SaaS row(s) removed, and ',
    'admin_shadow-saas-grip.grip_all_cleared_p4' => ' vendor record(s) cleared of stamped Grip telemetry.',
    'admin_shadow-saas-grip.grip_api_reference_intro' => 'Endpoint inventory for the Grip Security public API (server base <code>https://&lt;tenant&gt;.dep.grip.security/public</code>, auto-generated OpenAPI 3.1). The FairTPRM sync consumes the read (GET) endpoints marked <em>used by sync</em>; the complete inventory &mdash; including the Users, Workflows, Posture&nbsp;Management, AuditLogs, Alerts / Alerts&nbsp;V2, Actions, and AI&nbsp;Agents groups &mdash; is in the OpenAPI and Postman downloads below. Domain extraction normalizes URLs to their registrable domain (e.g. <code>https://www.united.com</code> → <code>united.com</code>, <code>http://color.redhat.com</code> → <code>redhat.com</code>).',
    'admin_shadow-saas-grip.grip_auth_help' => 'Authentication header: <code>access-token: &lt;your-token&gt;</code>. The Postman collection\'s <code>accessToken</code> variable is set to <code>REPLACE_ME</code>; substitute your tenant token before sending requests.',
    'admin_shadow-saas-grip.grip_base_url_help' => 'Tenant-prefixed Grip URL rooted at <code>/public/saas</code> (e.g. <code>https://tenant.dep.grip.security/public/saas</code>). Sibling endpoints (<code>/public/users</code>, <code>/public/alerts</code>) are derived from this host.',
    'admin_shadow-saas-grip.grip_base_url_label' => 'Server (Tenant Base URL)',
    'admin_shadow-saas-grip.grip_breach_help' => 'On each scheduled rehydration (and the manual <strong>Run&nbsp;Now</strong> below), Grip "Security Incident Detected" alerts are written into the <a href="breach-alerts.php">Breach&nbsp;/&nbsp;Cyber Alerts</a> system (deduplicated). Breaches for an onboarded vendor are linked to that vendor; breaches for an app with no onboarded vendor are still recorded and tagged <strong>Shadow&nbsp;SaaS</strong> with the number of users potentially impacted. Requires Grip enabled (above) <em>and</em> the Breach&nbsp;/&nbsp;Cyber Alert setting under <a href="admin.php?section=email">Email &amp; Alerts</a>.',
    'admin_shadow-saas-grip.grip_config_update_failed_prefix' => 'Failed to update Grip configuration: ',
