    'admin_shodan-srs.about_body' => 'Shodan is an internet intelligence platform that scans and indexes every internet-connected device it can find. The integration enables:<br><br><strong>• Port Scanning:</strong> Identify open ports on vendor infrastructure, including high-risk services (FTP, Telnet, RDP, SMB)<br><strong>• Vulnerability Detection:</strong> Discover known CVEs associated with vendor IP addresses and services<br><strong>• Service Identification:</strong> Catalog running services, software versions, and server configurations<br><strong>• Security Scoring:</strong> Generate a 0-100 security score based on exposed attack surface',
