    'admin_shodan-srs.about_note_body' => 'Shodan scores are complementary to UpGuard scores. UpGuard focuses on overall security posture (0-950 scale), while Shodan focuses on exposed infrastructure (0-100 scale). Both can be enabled simultaneously for comprehensive vendor assessments.',
