    'admin_shodan-srs.on_demand_help' => 'When enabled, Shodan will request an on-demand scan for any IPs it has no existing data for during scoring. This ensures coverage for domains Shodan hasn\'t previously scanned, but uses scan credits (1 credit per IP) and adds up to 3 minutes of wait time per scoring request while Shodan processes the scan. Recommended for vendors where Shodan returns no security signals.',
