    'admin_srs.about_custom_body' => 'Custom scoring allows you to manually enter security scores for vendors using external assessment tools or rating services.<br><br><strong>Score Range:</strong> 1-100 (percentage scale)<br><strong>Grading:</strong> A &ge; 90, B &ge; 75, C &ge; 60, D &ge; 40, F &lt; 40<br><br>When multiple scoring sources exist (UpGuard, Shodan, Custom), a combined average score is calculated and displayed across the application. This provides a unified view of each vendor\'s security posture from all available sources.',
    'admin_srs.about_custom_heading' => 'About Custom Scoring',
    'admin_srs.about_upguard_body' => 'UpGuard CyberRisk provides automated security ratings and continuous monitoring for third-party vendors. The integration enables:<br><br><strong>• Automated Security Scoring:</strong> Get instant security ratings (0-950) for vendors based on their external security posture<br><strong>• Risk Identification:</strong> Automatically identify high, medium, and low severity security risks<br><strong>• Trend Analysis:</strong> Track vendor security scores over time to identify improvements or degradation<br><strong>• Tier-Based Monitoring:</strong> Configure rescoring frequency based on vendor criticality',
    'admin_srs.about_upguard_heading' => 'About UpGuard CyberRisk',
    'admin_srs.about_upguard_learn_more' => 'Learn more about UpGuard CyberRisk &rarr;',
