    'admin_srs.cron_ondemand_heading' => '2. On-Demand Rescore Queue <span style="background: #dbeafe; color: #1e40af; padding: 2px 8px; border-radius: 10px; font-size: 11px; font-weight: 600; vertical-align: middle;">Required for "Use Cron"</span>',
