    // --- Back-filled 2.6.2 hardcoded page strings (auto-merged) ---
    'admin_api-integration.anthropic_api_key_help' => 'Sent as the <code>x-api-key</code> header. Stored AES-256 encrypted; leave blank to keep the existing key.',
    'admin_api-integration.anthropic_model_help' => 'e.g. <code>claude-opus-4-8</code>, <code>claude-sonnet-4-6</code>, <code>claude-haiku-4-5</code>. Web search runs automatically during Breach &amp; OSINT scans.',
    'admin_api-integration.custom_search_url_help' => 'Used by breach research to ground the model on fresh news. Sends <code>{"query": "...", "max_results": N}</code> with the same headers/secret as the API URL above. Leave blank to auto-derive - if API URL ends in <code>/v1/infer</code>, the system uses <code>/v1/safe-search</code> on the same host (FairTPRM orchestrator convention). If your backend has no search endpoint, leave blank: breach scans will run inference-only and likely return zero alerts.',
    'admin_api-integration.fair_model_help' => 'Used for FAIR risk analysis, assessment auto-fill, and contract extraction. Needs fast response (&lt;30s) and good JSON output. Works with both platforms. Leave blank to use the default model.',
    'admin_api-integration.headers_body_template_help' => 'One <code>-H \'Header: value\'</code> per line, plus a <code>--data-raw \'{...}\'</code> JSON body template. The literal token <code>SAMPLE</code> inside the JSON body is JSON-string-escaped and substituted with the dynamic prompt at request time (same dispatch model as OpenWebUI / LibreChat).',
    'admin_api-integration.js_copy_failed' => 'Copy failed - select and copy manually',
    'admin_api-integration.js_could_not_load_models' => 'Could not load models.',
    'admin_api-integration.js_could_not_load_models_prefix' => 'Could not load models: ',
    'admin_api-integration.js_example_copied' => 'Example copied to clipboard',
    'admin_api-integration.js_models_loaded_suffix' => ' model(s) loaded.',
    'admin_api-integration.js_postman_downloaded' => 'Postman collection downloaded',
    'admin_api-integration.js_select_a_model' => '- select a model -',
    'admin_api-integration.openai_api_key_help' => 'Sent as <code>Authorization: Bearer</code>. Stored AES-256 encrypted; leave blank to keep the existing key.',
    'admin_api-integration.openai_search_model_help' => 'Used only for Breach &amp; OSINT scans (needs a web-search-capable model). e.g. <code>gpt-4o-search-preview</code>, <code>gpt-4o-mini-search-preview</code>.',
    'admin_api-integration.secret_header_name_help' => 'HTTP header that carries the secret (e.g., <code>x-app-secret</code>, <code>Authorization</code>).',
    'admin_api-integration.secret_header_value_help' => 'Stored AES-256 encrypted. Once saved the value can never be viewed again - only replaced by entering a new value here. Injected into the request as <code>{Header Name}: {value}</code>; do not include this header in the textarea below.',
    'admin_fair-defaults.ai_analysis_heading' => 'AI-Assisted FAIR Analysis',
    'admin_fair-defaults.ai_analysis_help' => 'When enabled, analysts can use AI to estimate realistic ALE, primary/secondary loss magnitudes, and recommended cyber insurance coverage based on all available vendor security data (Shodan signals, UpGuard risks, vulnerability data, and financial context).',
    'admin_fair-defaults.ai_disabled_help' => 'AI-assisted FAIR calculations require an AI platform (OpenWebUI or LibreChat) to be enabled. <a href="admin.php?section=ai-integration">Configure AI Integration settings</a> first.',
    'admin_fair-defaults.ai_enable_checkbox_label' => 'Enable AI-Assisted FAIR Calculations',
    'admin_fair-defaults.ai_enable_help' => 'Adds an "AI-Assisted Analysis" button to the FAIR analysis form. The AI uses the FAIR model methodology along with all available vendor security intelligence (Shodan, UpGuard, CVEs, certifications) to estimate financial risk values. Analysts can review and accept or reject AI estimates before saving.',
    'admin_fair-defaults.annual_revenue_help' => 'Your organization\'s annual revenue. Set to 0 to disable revenue-based capping.',
    'admin_fair-defaults.annual_revenue_label' => 'Annual Revenue (USD)',
    'admin_fair-defaults.breach_cost_defaults_heading' => 'Breach Cost Defaults',
    'admin_fair-defaults.breach_cost_defaults_help' => 'Industry-standard per-record breach costs used in FAIR primary loss calculations. Based on Ponemon Institute and IBM Cost of a Data Breach reports.',
    'admin_fair-defaults.error_invalid_request' => 'Invalid request. Please try again.',
    'admin_fair-defaults.error_save_failed' => 'Failed to update calculation defaults',
    'admin_fair-defaults.org_financial_profile_heading' => 'Organization Financial Profile',
    'admin_fair-defaults.org_financial_profile_help' => 'Your organization\'s annual revenue is used to cap FAIR loss calculations at a realistic maximum. A vendor breach shouldn\'t produce a loss estimate that exceeds a reasonable percentage of your annual revenue.',
    'admin_fair-defaults.page_subtitle' => 'Configure default values for FAIR risk calculations, organization financial profile, and AI-assisted analysis.',
    'admin_fair-defaults.page_title' => 'FAIR Calculation Defaults',
    'admin_fair-defaults.pii_cost_per_record_help' => 'Cost per PII record if breached (Default: $160)',
    'admin_fair-defaults.pii_cost_per_record_label' => 'PII Breach Cost Per Record (USD)',
    'admin_fair-defaults.revenue_cap_pct_help' => 'Maximum ALE as a percentage of annual revenue (Default: 10%). For example, at $5M revenue and 10%, no single vendor\'s ALE will exceed $500,000.',
    'admin_fair-defaults.revenue_cap_pct_label' => 'Maximum Loss Cap (% of Annual Revenue)',
